colors=[2,3,4,6,7]
stencil={(0,2),(1,0),(1,1),(1,2),(1,3),(2,1),(2,2),(3,2)}
out=[]
for r in range(24):
    row=[]
    if r%5==4:
        row=[5]*24
    else:
        band=r//5; rr=r%5
        for c in range(24):
            if c%5==4:
                row.append(5)
            else:
                cc=c%5
                row.append(colors[band] if (rr,cc) in stencil else 0)
    out.append(row)
import json
print(json.dumps({'action':'submit','grid':out},separators=(',',':')))
